parameters.jsCode:
// Get input data
const items = $input.all();

const result = items.map(item => {
  let parsedOutput;

  try {
    // Parse the JSON string inside "output"
    parsedOutput = JSON.parse(item.json.output);
  } catch (error) {
    parsedOutput = { error: "Invalid JSON in output field" };
  }

  return {
    json: {
      description: parsedOutput.description || null,
      email_subject: parsedOutput.email?.subject || null,
      email_body: parsedOutput.email?.body || null
    }
  };
});

return result;
